"""Additional specifier types for glom.

This module provides extended specifier types that go beyond the basic
glom operations, enabling more advanced data transformation patterns.

"""

from __future__ import print_function

from .core import (T, S, Path, Spec as _Spec, glom, GlomError, SKIP, STOP,
                   TType, _MISSING, TargetRegistry, UnregisteredTarget)


class Auto(object):
    """Auto specifies a value that should be resolved from either the
    target (T) or the scope (S), depending on availability.

    If the key/attribute exists in the target, it is accessed from the
    target. Otherwise, it is looked up in the scope. This enables
    writing specs that work seamlessly with both local variables and
    target data.

    Args:
       spec: A key, attribute name, or other specifier to look up.

    >>> target = {'a': 1}
    >>> glom(target, Auto('a'))
    1
    >>> glom(target, Auto('b'), scope={'b': 2})
    2

    The spec can also be a full glom spec:

    >>> glom(target, Auto(T['a']))
    1

    """
    def __init__(self, spec):
        self.spec = spec

    def glomit(self, target, scope):
        # First try to resolve from target using the spec
        try:
            return scope[glom](target, self.spec, scope)
        except GlomError:
            # Fall back to scope lookup if it's a simple key
            if isinstance(self.spec, str):
                return scope[self.spec]
            raise


class Fill(object):
    """Fill specifies filling in missing keys/values with defaults.

    Fill works similarly to Coalesce but is designed for dict-like
    operations where you want to ensure certain keys exist in the
    output. Each item is a (key, subspec_or_default) pair.

    Args:
       items: A dict of {key: value} pairs where value can be a glom
          spec or a literal default value.

    >>> target = {'a': 1}
    >>> glom(target, Fill({'a': 'a', 'b': 'default'}))
    {'a': 1, 'b': 'default'}

    """
    def __init__(self, items=None, **kwargs):
        if items is None:
            items = kwargs
        self.items = items

    def glomit(self, target, scope):
        result = {}
        for key, value in self.items.items():
            try:
                if callable(getattr(value, 'glomit', None)):
                    result[key] = scope[glom](target, value, scope)
                elif isinstance(value, (str, int, float, bool, type(None))):
                    result[key] = value
                else:
                    result[key] = scope[glom](target, value, scope)
            except GlomError:
                # Use the value as a default if it's not a spec
                if isinstance(value, (str, int, float, bool, type(None))):
                    result[key] = value
                else:
                    raise
        return result


class Invoke(object):
    """Invoke calls a method on the target with optional arguments.

    Invoke is similar to Call but is designed for method invocation
    on the target object. It automatically passes the target as the
    first argument (like calling obj.method(*args, **kwargs)).

    Args:
       method: The method name or callable to invoke.
       args: Positional arguments to pass to the method.
       kwargs: Keyword arguments to pass to the method.

    >>> class Example:
    ...     def add(self, x, y):
    ...         return x + y
    >>> target = Example()
    >>> glom(target, Invoke('add', args=[1, 2]))
    3

    """
    def __init__(self, method, args=None, kwargs=None):
        self.method = method
        if args is None:
            args = ()
        if kwargs is None:
            kwargs = {}
        self.args = args
        self.kwargs = kwargs

    def glomit(self, target, scope):
        if callable(self.method):
            func = self.method
        else:
            func = getattr(target, self.method)

        # Evaluate any T-type args
        def _eval(v):
            if isinstance(v, TType):
                return scope[glom](target, v, scope)
            return v

        eval_args = [_eval(a) for a in self.args]
        eval_kwargs = {k: _eval(v) for k, v in self.kwargs.items()}

        return func(*eval_args, **eval_kwargs)

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, args=%r, kwargs=%r)' % (cn, self.method, self.args, self.kwargs)


class Iter(object):
    """Iter wraps a list spec with additional iteration options.

    Iter allows controlling how list iteration behaves, including
    handling of SKIP values and customizing iteration behavior.

    Args:
       subspec: The spec to apply to each item in the iterable.
       skip_none: Whether to skip None values during iteration.
       stop_on_none: Whether to stop iteration when a None value is encountered.

    >>> target = [1, 2, 3, 4]
    >>> glom(target, Iter(lambda x: x * 2))
    [2, 4, 6, 8]

    """
    def __init__(self, subspec, skip_none=False, stop_on_none=False):
        self.subspec = subspec
        self.skip_none = skip_none
        self.stop_on_none = stop_on_none

    def glomit(self, target, scope):
        try:
            iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
        except UnregisteredTarget as ut:
            raise TypeError('can only iterate on iterable targets, not %s type'
                            % type(target).__name__)

        try:
            iterator = iterate(target)
        except Exception as e:
            raise TypeError('failed to iterate on instance of type %r at %r (got %r)'
                            % (target.__class__.__name__, Path(*scope[Path]), e))

        ret = []
        for i, t in enumerate(iterator):
            val = scope[glom](t, self.subspec, scope.new_child({Path: scope[Path] + [i]}))
            if val is None and self.skip_none:
                continue
            if val is None and self.stop_on_none:
                break
            if val is SKIP:
                continue
            if val is STOP:
                break
            ret.append(val)
        return ret


class Let(object):
    """Let binds variables in the scope for later use.

    Let creates a temporary scope binding that lasts for the duration
    of the nested spec evaluation. This is useful for computing
    intermediate values that are used multiple times.

    Args:
       bindings: A dict mapping names to values or specs.
       spec: The spec to evaluate with the bound variables in scope.

    >>> target = {'a': 1, 'b': 2}
    >>> glom(target, Let({'total': T['a'] + T['b']}, {'sum': 'total'}))
    {'sum': 3}

    """
    def __init__(self, bindings, spec):
        self.bindings = bindings
        self.spec = spec

    def glomit(self, target, scope):
        # Create new scope with bindings
        new_scope = dict(scope)
        for name, value in self.bindings.items():
            if callable(getattr(value, 'glomit', None)):
                new_scope[name] = scope[glom](target, value, scope)
            elif isinstance(value, TType):
                new_scope[name] = scope[glom](target, value, scope)
            else:
                new_scope[name] = value

        # Evaluate spec with extended scope
        result = scope[glom](target, self.spec, scope.new_child(new_scope))
        return result

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, %r)' % (cn, self.bindings, self.spec)


class ROOT(object):
    """ROOT references the root target, regardless of nesting level.

    In deeply nested specs, ROOT always refers to the original target
    passed to glom(), rather than the current sub-target being
    processed.

    >>> target = {'a': {'b': {'c': 1}}}
    >>> glom(target, {'a': {'root': ROOT}})
    {'a': {'root': {'a': {'b': {'c': 1}}}}}

    ROOT is particularly useful in list iterations where you need
    access to the original data:

    >>> target = [{'id': 1, 'parent_id': None}, {'id': 2, 'parent_id': 1}]
    >>> def find_parent(item):
    ...     parent_id = item.get('parent_id')
    ...     if parent_id is None:
    ...         return None
    ...     return next((x for x in ROOT if x['id'] == parent_id), None)
    >>> glom(target, [{'id': 'id', 'parent': lambda t: find_parent(t)})]
    [{'id': 1, 'parent': None}, {'id': 2, 'parent': {'id': 1, 'parent_id': None}}]

    """
    def glomit(self, target, scope):
        # Get the root target from the scope chain
        # Walk up the scope chain to find the original target
        current_scope = scope
        while hasattr(current_scope, '_ChainMap__map'):
            for d in current_scope.maps:
                if T in d:
                    return d[T]
            current_scope = current_scope.parent
        # Fallback: return current target
        return target

    def __repr__(self):
        return 'ROOT'
